package com.cinenest.reporting.internal;
import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
import com.cinenest.payments.BankBalanceReport;import com.cinenest.rooms.VenueReportingClock;import com.cinenest.identity.ScopedAuthorization;import java.util.*;import java.time.*;
class BankReportControllerTest {
 @Test void localDateCohortsUseIanaDstNotFixedTwentyFourHourDays(){for(var sample:List.of(Map.entry("2026-03-08",23L),Map.entry("2026-11-01",25L))){var report=mock(BankBalanceReport.class);var clock=mock(VenueReportingClock.class);var auth=mock(ScopedAuthorization.class);UUID actor=UUID.randomUUID(),venue=UUID.randomUUID();when(clock.timezone(venue)).thenReturn(Optional.of("America/New_York"));when(auth.permits(actor,venue,"report.bank.synthetic.read",false)).thenReturn(true);var zero=new BankBalanceReport.Amounts("0","0","0","0","0","0","0","0");when(report.snapshot(eq(actor),any())).thenReturn(new BankBalanceReport.Snapshot(Instant.now(),"SYNTHETIC-BANK-BALANCES-V1",0,zero,List.of()));var controller=new BankReportController(report,clock,auth,true,366);controller.read(actor::toString,venue,Map.of("currency","LKR","from",sample.getKey(),"to",LocalDate.parse(sample.getKey()).plusDays(1).toString()));var capture=org.mockito.ArgumentCaptor.forClass(BankBalanceReport.Query.class);verify(report).snapshot(eq(actor),capture.capture());assertThat(Duration.between(capture.getValue().from(),capture.getValue().to()).toHours()).isEqualTo(sample.getValue());}}
 @Test void unconfiguredReportingFailsBeforeReadingSources(){var report=mock(BankBalanceReport.class);var clock=mock(VenueReportingClock.class);var auth=mock(ScopedAuthorization.class);UUID a=UUID.randomUUID(),v=UUID.randomUUID();when(auth.permits(a,v,"report.bank.synthetic.read",false)).thenReturn(true);var controller=new BankReportController(report,clock,auth,false,0);assertThatThrownBy(()->controller.read(a::toString,v,Map.of("currency","LKR"))).isInstanceOf(RuntimeException.class).hasMessageContaining("not configured");verify(report,never()).snapshot(any(),any());}
}
